file.content:
/** @brief Manage position fix and date-time from GNSS receiver. 
 * 
 * Based on u-blox 8 receiver integrated Beitian BN-880 module, using the UBX communications
 * protocol instead of the usual NMEA-183. The problem with NMEA is that it was really 
 * designed for boats, where close enough to see with binoculars was good enough (well, not
 * really but it makes for a good story). The real issue is that it's hard to get consistent
 * fix and time data by parsing NMEA sentences.
 * 
*/

#ifndef BGEIGIEZEN_GPS_SENSOR_H_
#define BGEIGIEZEN_GPS_SENSOR_H_

#include <Arduino.h>
#include <RBD_Timer.h>
#include <Worker.hpp>
#include <user_config.h>

#include <TeenyUbloxConnect.h>
#include "gps_platform_model.h"

struct GnssData {
  // When true, the item related to each Boolean is valid and updated in the
  // most recent poll of the gps_connector worker by the controller. If the 
  // gps_connector doesn't have a new fix because it only becomes available
  // every 1 second, then the corresponding Boolean becomes false.
  // If stale, render in gray/white text. 
  bool location_valid;
  bool date_valid;
  bool time_valid;

  bool valid() const {
    return location_valid && date_valid && time_valid;
  }

  enum Heading {
    UNKNOWN,
    NORTH,
    NORTHEAST,
    EAST,
    SOUTHEAST,
    SOUTH,
    SOUTHWEST,
    WEST,
    NORTHWEST,
  };

  // Position
  double latitude;  // Longitude: deg
  double longitude; // Longitude: deg
  double altitudeMSL;  // above mean sea level in meters
  double heading_degree; // in degrees
  Heading heading;

  // Confidence
  uint8_t satsInView;  // (NavSat) satellites used to calculate fix
  uint8_t  numSV;  // (NavPvt) Number of satellites used in Nav Solution
  double pdop;  // position dilution of precision (not horizontal)
  uint32_t hAcc;  // mm Horizontal accuracy estimate for Long/Lat
  uint32_t vAcc;  // mm Vertical accuracy estimate for Long/Lat
  int32_t  velN;  // mm/s NED north velocity
  int32_t  velE;  // mm/s NED east velocity
  int32_t  velD;  // mm/s NED down velocity
  int32_t  gSpeed;  // Ground Speed (2-D)
  int32_t  headMot;  // Heading of motion (2-D)
  uint32_t sAcc;
  uint32_t headAcc;
  bool invalidLlh;  // NAVPVT[78] flags3 bit 0


  // Date & Time
  uint16_t year;
  uint8_t month;
  uint8_t day;
  uint8_t hour;
  uint8_t minute;
  uint8_t second;

  // Debug info
  uint8_t protocolVersionHigh;
  uint8_t protocolVersionLow;

  // Per-satellite data from NMEA $GPGSV/$GPGSA (populated in NMEA fallback mode)
  struct NmeaSatEntry {
    uint8_t svId;
    int8_t  elev;
    int16_t azim;
    uint8_t cno;
    bool    svUsed;
    char    gnssIdType; // 'G'=GPS, 'R'=GLONASS, 'E'=Galileo, etc.
  };
  static constexpr uint8_t NMEA_MAX_SATS = 16;
  NmeaSatEntry nmea_sats[NMEA_MAX_SATS];
  uint8_t nmea_sat_count;
  uint32_t nmea_gsv_cycle; // incremented each time a complete GPGSV cycle is received
  bool nmea_mode;

};

/**
 * GPS device worker, produces the current GPS location.
 */
class GpsConnector : public Worker<GnssData> {
 public:

  explicit GpsConnector(TeenyUbloxConnect& _gnss, HardwareSerial& serial);

  virtual ~GpsConnector() = default;


  /**
   * Backup U-blox GPS memory (almanac, ephemeris, satellite data) to M5Stack NVS
   * @return true if backup was successful
   */
  bool backupGpsMemoryToNVS();

  /**
   * Restore U-blox GPS memory from M5Stack NVS for faster startup
   * @return true if restore was successful
   */
  bool restoreGpsMemoryFromNVS();

  /**
   * Save a warm-start seed (time/position) to SD card for faster startup without VBAT.
   * File path: /gnss/warm_seed.bin
   * @return true if file written
   */
  bool saveWarmStartSeedToSD();

  /**
   * Load warm-start seed from SD card and prepare for injection.
   * Current implementation validates and logs the seed.
   * @return true if seed loaded
   */
  bool injectWarmStartSeedFromSD();

  /**
   * Dump the GNSS database (UBX-MGA-DBD) to SD card.
   * File path: /gnss/dbd_latest.bin (raw UBX frames)
   */
  bool dumpDatabaseToSD();

  /**
   * Restore the GNSS database from SD card by replaying stored UBX frames.
   * File path: /gnss/dbd_latest.bin
   */
  bool restoreDatabaseFromSD();

  bool activate(bool retry) override;

  int8_t produce_data() override;

  /**
   * Set the GPS dynamic platform model
   * @param model The dynamic model to set (e.g., DYNMODEL_PORT, DYNMODEL_AIR4)
   * @param saveToFlash If true, saves the setting to flash memory so it persists after power cycles
   * @return true if successful, false otherwise
   */
  bool setDynamicModel(UbxDynamicModel model, bool saveToFlash);

  /**
   * Set the GPS dynamic platform model (RAM only version)
   * @param model The dynamic model to set (e.g., DYNMODEL_PORT, DYNMODEL_AIR4)
   * @return true if successful, false otherwise
   */
  bool setDynamicModel(UbxDynamicModel model);

  /**
   * Get the current GPS dynamic platform model
   * @return The current dynamic model
   */
  UbxDynamicModel getDynamicModel();

  /**
   * Read the current dynamic model directly from the GPS module
   * @return true if successful, false otherwise
   */
  bool readDynamicModelFromGPS();

  /**
   * Send a raw UBX message to the GPS module
   * @param msgClass UBX message class
   * @param msgID UBX message ID
   * @param payload Payload data
   * @param payloadSize Size of the payload
   * @return true if successful, false otherwise
   */
  bool sendUBXMessage(uint8_t msgClass, uint8_t msgID, const uint8_t* payload, size_t payloadSize);
  /**
   * Request the GNSS module to enter Backup mode and save its state.
   * Uses UBX-RXM-PMREQ with flags = 0x00000001.
   * Should be called just before power is removed.
   * @return true if the UBX frame was sent.
   */
  bool requestBackup();

  /**
   * Calculate UBX message checksum
   * @param data Data to calculate checksum for
   * @param len Length of data
   * @param cka Pointer to store CK_A
   * @param ckb Pointer to store CK_B
   */
  void calculateChecksum(const uint8_t* data, size_t len, uint8_t* cka, uint8_t* ckb);

 protected:
  void deactivate() override;

 private:
  /* u-blox UBX protocol query PVT gets position, velocity & time in one call.
   * The call returns false if no new fix has been received. In other words,
   * each call only succeeds once until the next fix update.
   * Use pdop and satsInView to determine acceptability.
  */
  TeenyUbloxConnect& _gnss;
  HardwareSerial& _serial_conn;
  uint32_t _tried_115200_at;
  uint32_t _tried_38400_at;
  uint32_t _tried_9600_at;
  uint32_t _tried_4800_at;
  uint32_t _init_at;
  bool _raw_dump_done;

  // NMEA fallback mode (used when GPS TX is connected but RX is not)
  bool _nmea_mode;
  char _nmea_buf[128];
  uint8_t _nmea_len;
  uint8_t _nmea_used_svids[12]; // SV IDs used in nav solution (from $GPGSA)
  uint8_t _nmea_used_count;

  int8_t produceDataNmea();
  bool parseNmeaSentence(const char* sentence);
  static double nmeaCoordToDecimal(const char* coord, char direction);

  double _last_latitude;
  double _last_longitude;

  // Current GPS dynamic model
  UbxDynamicModel _current_model = DYNMODEL_PORT;

  // Age each item. If the corresponding timer times out, it's stale.
  RBD::Timer location_timer{GPS_FIX_AGE_LIMIT};
  RBD::Timer date_timer{GPS_FIX_AGE_LIMIT};
  RBD::Timer time_timer{GPS_FIX_AGE_LIMIT};
  RBD::Timer time_getpvt{GPS_FIX_AGE_LIMIT};  // if no response from getPVT()
};

#endif //BGEIGIEZEN_GPS_SENSOR_H_

//
// Created by Jelle Bouwhuis on 12/27/19.
//

#ifndef SENSOR_HANDLER_INCLUDE_ACTIVATABLE_HPP_
#define SENSOR_HANDLER_INCLUDE_ACTIVATABLE_HPP_

/**
 * Some abstract class used by the receiver and observer
 */
class Activatable {
 public:
  typedef enum State {
    e_state_inactive,
    e_state_active,
    e_state_activating_failed,
  } State;

  Activatable();

  /**
   * Returns true if worker/handler is active
   * @return
   */
  bool active() const;

  /**
   * Returns current state of the worker/handler
   * @return
   */
  State get_active_state() const;

  /**
   * Activates / deactivates the data worker/handler. If the activate / deactivate fails, status wont change
   * Requires the data handler to be initialized
   * @param active: true to activate, false to deactivate
   */
  virtual bool set_active(bool _activate) final;

 protected:

  /**
   * Initializes this (called once, when registered in the aggregator)
   */
  virtual void initialize() {}

  /**
   * Perform an activate function, will be called when set_active(true)
   * Override this when the data handler will be activated/deactivated in times. The deactivate can clean up.
   * Example, use of wifi or bluetooth connection
   * @return true if activate was success. if false, object will not be activated (and wont be used)
   */
  virtual bool activate(bool retry);

  /**
   * Perform an deactivate function, will be called when set_active(false)
   * Override this to cleanup the activation... shut down connections or other
   */
  virtual void deactivate();

 private:
  State active_state;
};

#endif //SENSOR_HANDLER_INCLUDE_ACTIVATABLE_HPP_

content.text:
The `active()` method is defined in `Activatable.hpp` and is inherited by `GpsConnector` through `Worker → Activatable`. It's used dozens of places in the codebase with `GpsConnector` — the IDE diagnostic is a false positive (the language server is confused, not the compiler).

The change is correct. The fix mirrors the existing geiger counter grace period pattern exactly:

```cpp
// Before (no grace period):
if (required_gps && !workers.worker<GpsConnector>(k_worker_gps_connector)->active())

// After (15s grace period, matching M7 NMEA scan time):
if (required_gps && millis() > 15000 && !workers.worker<GpsConnector>(k_worker_gps_connector)->active())
```

The M7 baud-rate scan takes ~11-12s before detecting NMEA-only mode, so the 15-second grace period suppresses the false boot-time error while still catching genuine GPS hardware failures shortly after.
